javascript:
async function cargarInicio() {
  // Cargar Categorías
  await cargarCategorias();

  // Cargar Componentes Destacados
  await cargarDestacados();
}

async function cargarCategorias() {
  const res = await frappe.call({
    method: 'frappe.client.get_list',
    args: {
      doctype: 'Categoria',
      fields: ['name', 'nombre'],
      order_by: 'nombre asc'
    }
  });

  let html = '';
  res.message.forEach(cat => {
    html += `
      <div class="col-md-2 col-sm-4 col-6 mb-3">
        <button onclick="irACategoria('${cat.name}', '${cat.nombre}')" 
                class="btn btn-outline-primary w-100 py-3 fw-medium">
          ${cat.nombre}
        </button>
      </div>`;
  });

  document.getElementById('categorias-container').innerHTML = html;
}

async function cargarDestacados() {
  const res = await frappe.call({
    method: 'frappe.client.get_list',
    args: {
      doctype: 'Componente',
      fields: ['name', 'nombre', 'precio', 'estado', 'foto'],
      limit_page_length: 8,
      order_by: 'creation desc'
    }
  });

  let html = '';
  res.message.forEach(comp => {
    html += `
      <div class="col-md-3 col-sm-6 mb-4">
        <div class="card h-100">
          ${comp.foto ? `<img src="${comp.foto}" class="card-img-top" style="height: 180px; object-fit: cover;">` : ''}
          <div class="card-body">
            <h6 class="card-title">${comp.nombre}</h6>
            <p class="text-success fw-bold">${comp.precio || 0} €</p>
            <small class="text-muted">${comp.estado || ''}</small>
          </div>
        </div>
      </div>`;
  });

  document.getElementById('destacados-container').innerHTML = html || '<p class="text-center">No hay componentes destacados</p>';
}

function irACategoria(cat_name, cat_nombre) {
  window.location.href = `/rebuild-categoria?categoria=${cat_name}`;
}

function buscarComponentes() {
  const termino = document.getElementById('search-input').value;
  if (termino) {
    alert("Buscando: " + termino + "\n(Próximamente implementaremos búsqueda avanzada)");
  }
}

// Funciones del Popup de Usuario
function mostrarPopupUsuario() {
  document.getElementById('userPopup').style.display = 'block';
  mostrarLogin();
}

function cerrarPopup() {
  document.getElementById('userPopup').style.display = 'none';
}

function mostrarLogin() {
  document.getElementById('loginForm').style.display = 'block';
  document.getElementById('registerForm').style.display = 'none';
  document.getElementById('popupTitle').textContent = 'Iniciar Sesión';
}

function mostrarRegistro() {
  document.getElementById('loginForm').style.display = 'none';
  document.getElementById('registerForm').style.display = 'block';
  document.getElementById('popupTitle').textContent = 'Crear Cuenta';
}

function iniciarSesion() {
  const email = document.getElementById('login_email').value;
  const password = document.getElementById('login_password').value;

  if (!email || !password) {
    alert("Por favor completa todos los campos");
    return;
  }
  alert("Inicio de sesión (funcionalidad en desarrollo)");
  cerrarPopup();
}

async function registrarUsuario() {
  const nombre = document.getElementById('reg_nombre').value;
  const email = document.getElementById('reg_email').value;
  const password = document.getElementById('reg_password').value;

  if (!nombre || !email || !password) {
    alert("Por favor completa todos los campos");
    return;
  }

  try {
    await frappe.call({
      method: 'frappe.client.insert',
      args: {
        doc: {
          doctype: "Usuario",
          nombre: nombre,
          email: email,
          password: password
        }
      }
    });
    alert("¡Cuenta creada correctamente!");
    mostrarLogin();
  } catch (e) {
    alert("Error: " + (e.message || e));
  }
}

// Cargar todo al iniciar la página
frappe.ready(() => {
  cargarInicio();
});

async function cargarCategorias() {
  const res = await frappe.call({
    method: 'frappe.client.get_list',
    args: {
      doctype: 'Categoria',
      fields: ['name', 'nombre']
    }
  });

  let html = '';
  res.message.forEach(cat => {
    html += `
      <div class="col-md-4 col-sm-6 mb-4">
        <div class="card h-100 text-center cursor-pointer" onclick="mostrarComponentes('${cat.name}', '${cat.nombre}')">
          <div class="card-body">
            <h5 class="card-title">${cat.nombre}</h5>
            <p class="text-muted">Ver componentes →</p>
          </div>
        </div>
      </div>`;
  });

  document.getElementById('categorias-container').innerHTML = html;
}

async function mostrarComponentes(cat_name, cat_nombre) {
  document.getElementById('categorias-container').style.display = 'none';
  document.getElementById('componentes-section').style.display = 'block';
  document.getElementById('categoria-titulo').textContent = `Componentes - ${cat_nombre}`;

  const res = await frappe.call({
    method: 'frappe.client.get_list',
    args: {
      doctype: 'Componente',
      filters: { id_categoria: cat_name },
      fields: ['name', 'nombre', 'precio', 'estado', 'foto']
    }
  });

  let html = '';
  res.message.forEach(comp => {
    html += `
      <div class="col-md-3 col-sm-6 mb-4">
        <div class="card h-100">
          ${comp.foto ? `<img src="${comp.foto}" class="card-img-top" style="height: 180px; object-fit: cover;">` : ''}
          <div class="card-body">
            <h6 class="card-title">${comp.nombre}</h6>
            <p class="text-success fw-bold">${comp.precio || 0} €</p>
            <p class="text-muted small">${comp.estado || ''}</p>
            <button class="btn btn-primary btn-sm w-100">Añadir al carrito</button>
          </div>
        </div>
      </div>`;
  });

  document.getElementById('componentes-container').innerHTML = html || '<p class="text-center">No hay componentes en esta categoría.</p>';
}

function volverACategorias() {
  document.getElementById('categorias-container').style.display = 'flex';
  document.getElementById('componentes-section').style.display = 'none';
}

// Cargar categorías al entrar en la página
frappe.ready(() => {
  cargarCategorias();
});

